#if defined(__HIPCC__)
__device__ inline float LieRopeFrequency(const DeviceRope* rope, float theta,
                                        std::uint32_t pair, std::uint32_t dim) {
  if (rope && rope->lie_frequencies && rope->lie_rotary_dim == dim)
    return rope->lie_frequencies[pair];
  return powf(theta, -2.0F * static_cast<float>(pair) / static_cast<float>(dim));
}
__device__ inline void LieRopeScale(const DeviceRope* rope, float* sine, float* cosine) {
  if (rope && rope->lie_frequencies) {
    *sine *= rope->lie_attention;
    *cosine *= rope->lie_attention;
  }
}

