void DeviceInput::SetRopeScaling(const float* frequencies, std::uint32_t rotary_dim,
                                 float attention, hipStream_t stream) {
  if (!frequencies || !rotary_dim || (rotary_dim & 1) || !(attention > 0))
    throw std::invalid_argument("invalid LIE RoPE descriptor");
  lie_frequencies_ = frequencies;
  lie_attention_ = attention;
  lie_rotary_dim_ = rotary_dim;
  if (!descriptor_) Check(hipMalloc(&descriptor_, sizeof(DeviceRope)));
  const DeviceRope descriptor{positions_, layout_.PrefixLength(), layout_.Delta(),
                              lie_frequencies_, lie_attention_, lie_rotary_dim_};
  Check(hipMemcpyAsync(descriptor_, &descriptor, sizeof(descriptor),
                       hipMemcpyHostToDevice, stream));
  Check(hipStreamSynchronize(stream));
}

